code='''def transform(grid):
    out=[row[:] for row in grid]
    n,m=len(grid),len(grid[0])
    colors={v for row in grid for v in row if v!=7}
    for color in colors:
        cells={(r,c) for r in range(n) for c in range(m) if grid[r][c]==color}
        seen=set()
        for start in cells:
            if start in seen: continue
            stack=[start]; seen.add(start); comp=set()
            while stack:
                y,x=stack.pop(); comp.add((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if p in cells and p not in seen: seen.add(p); stack.append(p)
            ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
            if min(ys)==max(ys) or min(xs)==max(xs): continue
            for r in range(n):
                runs=sorted(c for y,c in comp if y==r)
                if runs:
                    # Extend every maximal horizontal run.
                    groups=[]
                    for c in runs:
                        if not groups or c>groups[-1][-1]+1: groups.append([c])
                        else: groups[-1].append(c)
                    for g in groups:
                        for c in (g[0]-1,g[-1]+1):
                            if 0<=c<m and out[r][c]==7: out[r][c]=2
            for c in range(m):
                runs=sorted(r for r,y in comp if y==c)
                groups=[]
                for r in runs:
                    if not groups or r>groups[-1][-1]+1: groups.append([r])
                    else: groups[-1].append(r)
                for g in groups:
                    for r in (g[0]-1,g[-1]+1):
                        if 0<=r<n and out[r][c]==7: out[r][c]=2
    return out
'''
